&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Life &amp;amp; Family Support&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Volunteer and Community Initiatives&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Learning &amp;amp; Development&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Exclusive Perks&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;span data-olk-copy-source=&quot;MailCompose&quot;&gt;Please review our &lt;/span&gt;&lt;a id=&quot;OWAf3b48604-66ff-cab5-fa36-85c2d05d437e&quot; class=&quot;OWAAutoLink&quot; href=&quot;https://nam11.safelinks.protection.outlook.com/?url=http%3A%2F%2Fdocs.hasbro.com%2Fprivacy%2Fjob-applicant&amp;amp;data=05%7C02%7CMaria.Hughes%40wizards.com%7C73f450b2476e4441be3308dec7006d14%7C701edd3ec7a84789b1ce8a243620d68f%7C0%7C0%7C639167001791388387%7CUnknown%7CTWFpbGZsb3d8eyJFbXB0eU1hcGkiOnRydWUsIlYiOiIwLjAuMDAwMCIsIlAiOiJXaW4zMiIsIkFOIjoiTWFpbCIsIldUIjoyfQ%3D%3D%7C0%7C%7C%7C&amp;amp;sdata=QzsYnPcynaB0OC2yYMSHab2TyW8jOlZQWyr87FBwDt8%3D&amp;amp;reserved=0&quot; data-auth=&quot;NotApplicable&quot;&gt;Applicant Privacy Notice&lt;/a&gt; to learn how we collect, use, and protect your personal information in connection with the application process.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
